contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function with one input parameter to quantify over
    function run(bool dummy) public payable {
        require(true);

        // Make the state-changing call as a top-level statement and record whether it reverted
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule: for any input (dummy), either the call reverted or c's balance is zero
        assert(reverted || address(c).balance == 0);
    }

    receive() external payable {}
}

